import os
from pathlib import Path
from dotenv import dotenv_values

def load_env(env="development", base="{{env_dir}}"):
    base = Path(base)
    files = [
        base / ".env",
        base / f".env.{env}",
        base / ".env.local",
        base / f".env.{env}.local",
    ]
    merged = {}
    for f in files:
        if f.exists():
            print(f"loading {f}")
            merged.update({k: v for k, v in dotenv_values(f).items() if v is not None})
    for k, v in merged.items():
        os.environ.setdefault(k, v)
    return merged

if __name__ == "__main__":
    cfg = load_env(os.getenv("APP_ENV", "development"))
    print(cfg)
